      "name": "Finset.nnnorm_prod_le",
      "module_name": "Mathlib.Analysis.Normed.Ring.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_4} {α : Type u_5} [inst : NormedCommRing α] [NormOneClass α] (s : Finset ι) (f : ι → α),\n  ‖∏ i ∈ s, f i‖₊ ≤ ∏ i ∈ s, ‖f i‖₊"
    },
    {
      "name": "List.nnnorm_prod_le",
      "module_name": "Mathlib.Analysis.Normed.Ring.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} [inst : SeminormedRing α] [NormOneClass α] (l : List α), ‖l.prod‖₊ ≤ (List.map nnnorm l).prod"
    },
    {
      "name": "Multipliable.norm_tprod",
      "module_name": "Mathlib.Topology.Algebra.InfiniteSum.Field",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {E : Type u_2} [inst : SeminormedCommRing E] [NormMulClass E] [NormOneClass E] {f : α → E},\n  Multipliable f → ‖∏' (i : α), f i‖ = ∏' (i : α), ‖f i‖"
    },
    {
      "name": "NormedDivisionRing.toNormMulClass",
      "module_name": "Mathlib.Analysis.Normed.Field.Basic",
      "kind": "instance",
      "type": "∀ {α : Type u_2} [inst : NormedDivisionRing α], NormMulClass α"
    },
    {
      "name": "Multipliable.norm",
      "module_name": "Mathlib.Topology.Algebra.InfiniteSum.Field",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {E : Type u_2} [inst : SeminormedCommRing E] [NormMulClass E] [NormOneClass E] {f : α → E},\n  Multipliable f → Multipliable fun x => ‖f x‖"
    },
    {
      "name": "Polynomial.coeff_mul",
      "module_name": "Mathlib.Algebra.Polynomial.Coeff",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] (p q : Polynomial R) (n : ℕ),\n  (p * q).coeff n = ∑ x ∈ Finset.antidiagonal n, p.coeff x.1 * q.coeff x.2"
    },
    {
      "name": "Prod.normedRing",
      "module_name": "Mathlib.Analysis.Normed.Ring.Basic",
      "kind": "instance",
      "type": "{α : Type u_2} → {β : Type u_3} → [NormedRing α] → [NormedRing β] → NormedRing (α × β)"
    },
    {
      "name": "PadicInt.instNormMulClass",
